(() => {
 'use strict';
 const A=window.AdminUI,{S,esc,money,link,button,actions,pill,panel,table,facts,notice,empty,field,select,textarea,check,list,details,grid,form,heading,modal,download,commit,scenario,queue,screens,handlers,forms,binders,toast,render}=A;
 const getProduct=()=>{const p=S.state.products.find(p=>p.id===(A.params.get('id')||S.state.products[0].id));if(!p)throw Error('Artwork not found.');return p;};
 function productCards(products){return `<div class="product-grid">${products.map(p=>`<a class="product-card" href="#products/artwork?id=${esc(p.id)}"><div class="artwork-preview"><img src="${esc(p.image)}" alt="${esc(p.title)}" loading="lazy"></div><div>${pill(p.status,p.status==='Draft'?'warn':'')}<h2>${esc(p.title)}</h2><p>${esc(p.collection)} · ${esc(p.style)}</p><small>${esc(p.id)} · A2 · three frame finishes</small></div></a>`).join('')}</div>`;}
 screens.products=()=>heading('Artworks','The approved catalogue, with its files, variants and readiness in one place.',`<form id="product-search" class="filter-form">${field('q','Find an artwork','','search','',false)}${select('status','Catalogue state',['All','Active','Draft','In review','Hidden','Retired'])}<button type="reset" class="button secondary">Clear</button></form><p id="product-count" class="small" role="status">${S.state.products.length} artwork records</p><div id="product-results">${productCards(S.state.products)}</div>`,actions(button('art-new','New draft artwork'),button('export','Export catalogue',{kind:'products'},'button secondary')));
 binders.products=()=>{const f=document.querySelector('#product-search');if(!f)return;const update=()=>{const q=f.elements.q.value.toLowerCase(),status=f.elements.status.value,rows=S.state.products.filter(p=>(status==='All'||p.status===status)&&[p.id,p.title,p.collection,p.style].join(' ').toLowerCase().includes(q));document.querySelector('#product-count').textContent=rows.length+' artwork records';document.querySelector('#product-results').innerHTML=rows.length?productCards(rows):empty('No matching artworks','Clear the search or choose a different catalogue state.','products','Show all artworks');};f.oninput=update;f.onsubmit=e=>{e.preventDefault();update();};f.onreset=e=>{e.preventDefault();f.elements.q.value='';f.elements.status.value='All';update();};};
 handlers['art-new']=()=>{S.guard('catalogue');modal('Create a draft artwork','This adds a local sample draft using the existing A2 template and three finishes. It does not expand the public catalogue.',field('title','Working title')+select('collection','Collection',[...new Set(S.state.products.map(p=>p.collection))])+textarea('copy','Draft description'),d=>S.mutate('CATALOGUE','Create draft artwork',()=>{const p=S.clone(S.state.products[0]);Object.assign(p,{id:'DRAFT-'+(S.state.products.length+1),slug:'draft-'+(S.state.products.length+1),title:d.title,copy:d.copy,collection:d.collection,status:'Draft',sample:false,rights:false,fileApproved:false,version:1,history:[],image:S.state.products[0].image,imageNote:'Existing artwork image used as a draft placeholder'});S.state.products.push(p);}),'Create local draft');};
 const readiness=p=>[!p.title.trim()?'Artwork title missing':null,!p.copy?.trim()?'Description missing':null,!p.rights?'Rights evidence not approved':null,!p.sample?'Physical sample not approved':null,!p.fileApproved?'Production file not approved':null,p.imageNote?'Replace the draft placeholder image':null,...Object.entries(p.prices).filter(([,v])=>!Number.isSafeInteger(v)||v<=0).map(([k])=>'Invalid '+k+' price')].filter(Boolean);
 function remember(p,reason){const snap=S.clone(p);delete snap.history;p.history.unshift({at:S.now(),reason,snapshot:snap});p.version++;}
 screens['products/artwork']=()=>{const p=getProduct(),missing=readiness(p);return heading(p.title,p.id+' · '+p.collection+' · catalogue revision v'+p.version,link('products','← Artworks')+`<div class="status-strip">${pill(p.status,p.status==='Draft'?'warn':'')}${pill('A2 · 42 × 59.4 cm','neutral')}${pill('Three frame finishes','neutral')}</div>`+(missing.length?notice('Not ready to publish',missing.map(esc).join(' · '),'warn'):'')+grid(panel('Artwork details',form('artwork',field('title','Artwork title',p.title)+textarea('copy','Product description',p.copy)+select('collection','Collection',[...new Set(S.state.products.map(p=>p.collection))],p.collection)+field('style','Art style',p.style)+field('moods','Moods',p.moods?.join(', ')||'','text','Comma-separated existing metadata',false)+field('rooms','Rooms',p.rooms?.join(', ')||'','text','Comma-separated existing metadata',false)+`<div class="field-grid">${Object.entries(p.prices).map(([k,v])=>field(k,k+' price (INR)',v/100,'number')).join('')}</div>`+field('lead','Sample lead time',p.lead||'5–7 working days')+check('featured','Featured in the existing collection template',p.featured)+textarea('reason','Revision reason'),'Save local draft revision',{id:p.id,version:p.version}))+details('Variant register',table('Existing variants',['Code','Format / finish','Approved prototype price','Availability'],Object.entries(p.prices).map(([k,v])=>[esc(p.id+'-A2-'+k.toUpperCase()),'A2 · '+esc(k),money(v),p.status==='Active'?'Active sample':'Not offered']))),panel('Preview & files',`<div class="artwork-preview"><img src="${esc(p.image)}" alt="${esc(p.title)}"></div>`+(p.imageNote?notice('Draft image',esc(p.imageNote),'warn'):'')+facts([['Public display image','Read-only approved asset reference'],['Private print file',esc(p.id)+'-print-'+esc(p.fileVersion)],['Rights / physical sample',`${p.rights?'Approved sample':'Missing rights'} / ${p.sample?'Approved sample':'Missing physical sample'}`]])+actions(link('products/preview?id='+p.id,'Preview artwork','button secondary'),link('products/files?id='+p.id,'Files & approvals','button secondary')))+panel('Publication',actions(button('art-publish','Review publication',{id:p.id}),button('art-status','Change visibility',{id:p.id},'button secondary'))+`<p class="small">Changes affect this prototype’s local catalogue. Existing purchases keep their prices and released jobs keep their print file.</p>`))+panel('Revision & rollback history',p.history.length?table('Catalogue revisions',['Previous version','Reason / date','Restore'],p.history.map((r,n)=>['v'+r.snapshot.version,esc(r.reason)+`<small>${esc(r.at)}</small>`,button('art-rollback','Preview rollback',{id:p.id,index:n},'button secondary')])):'<p class="small">No local revisions yet. Saved revisions remain recoverable.</p>'));};
 forms.artwork=(d,{id,version})=>{S.guard('catalogue');const p=S.state.products.find(p=>p.id===id);if(p.version!==version)throw Error('This artwork changed. Reload its latest revision.');const prices=Object.fromEntries(['black','white','antique-gold'].map(k=>[k,Math.round(Number(d[k])*100)]));if(Object.values(prices).some(v=>!Number.isSafeInteger(v)||v<=0))throw Error('Each existing finish needs a valid positive price.');commit(id,'Catalogue draft revision',()=>{remember(p,d.reason);Object.assign(p,{title:d.title,copy:d.copy,collection:d.collection,style:d.style,moods:d.moods.split(',').map(x=>x.trim()).filter(Boolean),rooms:d.rooms.split(',').map(x=>x.trim()).filter(Boolean),prices,lead:d.lead,featured:Boolean(d.featured),status:'Draft'});},d.reason);};
 screens['products/preview']=()=>{const p=getProduct();return heading('Artwork preview','Local catalogue preview using the current artwork template facts.',grid(panel(p.title,`<div class="artwork-preview"><img src="${esc(p.image)}" alt="${esc(p.title)}"></div>`),panel('Customer-facing facts',`<p>${esc(p.copy)}</p>`+facts([['Collection / style',esc(p.collection)+' / '+esc(p.style)],['Format','A2 · 42 × 59.4 cm'],['Finishes',Object.entries(p.prices).map(([k,v])=>esc(k)+' · '+money(v)).join('<br>')],['Availability',esc(p.status)],['Lead time',esc(p.lead||'Approved public lead-time copy retained')]])))+actions(link('products/artwork?id='+p.id,'Return to editor','button secondary'),button('art-publish','Review publication',{id:p.id})));};
 handlers['art-publish']=({id})=>{S.guard('settings');const p=S.state.products.find(p=>p.id===id);modal('Publish this local artwork revision?','Review required approvals. The locked public prototype and historical purchases stay unchanged.',readiness(p).length?notice('Publication blocked',readiness(p).map(esc).join(' · '),'error'):facts([['Artwork',esc(p.title)],['Revision','v'+p.version],['Required evidence','Rights, file and physical sample approved in the demo']]),()=>S.mutate(id,'Approve local publication',()=>{const failures=readiness(p);if(failures.length)throw Error(failures.join(' · '));remember(p,'Owner approved sample publication');p.status='Active';p.approvedBy=S.names[S.state.role];p.approvedAt=S.now();}),'Publish locally');};
 handlers['art-status']=({id})=>{S.guard('catalogue');const p=S.state.products.find(p=>p.id===id);modal('Change catalogue visibility','Hiding or retiring preserves history and never cancels existing production.',select('status','State',['Draft','In review','Hidden','Retired'],p.status)+textarea('reason','Reason'),d=>S.mutate(id,'Catalogue visibility',()=>{remember(p,d.reason);p.status=d.status;},d.reason),'Save visibility');};
 handlers['art-rollback']=({id,index})=>{S.guard('settings');const p=S.state.products.find(p=>p.id===id),r=p.history[index];modal('Restore catalogue content from v'+r.snapshot.version+'?','The restored content becomes a draft for review. Issued documents and pinned job files stay intact.',facts([['Title',esc(r.snapshot.title)],['File metadata',esc(r.snapshot.fileVersion)],['Reason',esc(r.reason)]]),()=>S.mutate(id,'Catalogue rollback',()=>{const history=S.clone(p.history),version=p.version;remember(p,'Before rollback');const before=p.history[0];Object.assign(p,S.clone(r.snapshot),{history:[before,...history],version:version+1,status:'Draft'});}), 'Restore as draft');};
 screens['products/files']=()=>{const p=getProduct();return heading('Files & approvals · '+p.id,'Separate public artwork assets from private production files and evidence.',link('products/artwork?id='+p.id,'← Artwork editor')+grid(panel('Approval record',form('files',field('version','Proposed print file version',p.fileVersion)+field('dimensions','Print dimensions','A2 · 42 × 59.4 cm')+field('rightsRef','Rights evidence reference',p.rightsRef||'RIGHTS-DEMO-1')+select('publicImage','Sample display asset',window.AdminCatalogue.map(x=>[x.id,x.title]),p.id)+check('imageReviewed','I reviewed the selected sample image for this draft')+check('rights','Rights reviewed and approved in this sample',p.rights)+check('sample','Physical product sample approved in this sample',p.sample)+check('approved','Print file approved in this sample',p.fileApproved)+textarea('reason','Approval or file-change reason'),'Save file approval revision',{id:p.id})),panel('File boundaries',facts([['Public display file',esc(p.image)],['Private production file',esc(p.id)+'-print-'+esc(p.fileVersion)],['Private content','No real master file is exposed by this prototype'],['Approval owner / date',esc(p.approvedBy||'Sample studio approval')+' / '+esc(p.approvedAt||'13 September 2026')],['Pinned jobs',String(S.state.orders.flatMap(o=>o.items).filter(i=>i.artId===p.id&&i.stage>=2).length)+' released jobs retain their existing version']]))+notice('Changing a file affects approval','A new file must be reviewed explicitly. It never silently replaces the version pinned to released work.')));};
 forms.files=(d,{id})=>{S.guard('catalogue');if(!/^v[1-9]\d*$/.test(d.version))throw Error('Use a file version such as v3 or v4.');commit(id,'File / sample approval revision',()=>{const p=S.state.products.find(p=>p.id===id);remember(p,d.reason);if(d.imageReviewed){p.image=window.AdminCatalogue.find(x=>x.id===d.publicImage).image;p.imageNote=null;}Object.assign(p,{fileVersion:d.version,fileApproved:Boolean(d.approved),sample:Boolean(d.sample),rights:Boolean(d.rights),rightsRef:d.rightsRef,approvedBy:S.names[S.state.role],approvedAt:S.now(),status:'Draft'});},d.reason);};
 screens['products/collections']=()=>heading('Collections','Display order and featuring within the approved public structure.',[...new Set(S.state.products.map(p=>p.collection))].map(name=>panel(name,table(name+' artwork order',['Position','Artwork','Featuring','Move'],S.state.products.filter(p=>p.collection===name).map((p,n)=>[String(n+1),link('products/artwork?id='+p.id,p.title),p.featured?'Featured':'Standard',actions(button('collection-move','Move up',{id:p.id,direction:-1},'button secondary'),button('collection-move','Move down',{id:p.id,direction:1},'button secondary'))])))).join(''));
 handlers['collection-move']=({id,direction})=>{S.guard('catalogue');const products=S.state.products,p=products.find(p=>p.id===id),group=products.filter(x=>x.collection===p.collection),n=group.indexOf(p),other=group[n+direction];if(!other){toast('This artwork is already at the '+(direction<0?'start':'end')+' of its collection.');return;}commit(id,'Collection display order',()=>{const a=products.indexOf(p),b=products.indexOf(other);[products[a],products[b]]=[products[b],products[a]];});};
 screens['products/materials']=()=>heading('Materials & suppliers','Usable stock, owned reservations and incoming deliveries stay distinct.',scenario()+queue(table('Component availability',['Component','Usable on hand','Reserved','Available now','Incoming','Next action'],S.state.materials.map(m=>[link('products/material?id='+m.id,m.name)+`<small>${esc(m.unit)}</small>`,m.supplierOwned?'Supplier holds stock':m.stock,S.available(m).reserved,m.supplierOwned?'Confirm allocation':S.available(m).free,m.incoming+' (not received)',link('products/material?id='+m.id,'Review movements')])) )+panel('Simple reorder list',list(S.state.materials.filter(m=>S.available(m).free<5||m.incoming>0).map(m=>esc(m.name)+' · '+esc(m.supplier)+' · '+esc(m.lead)+' · '+m.incoming+' incoming')))+notice('Reservations protect accepted orders','Two jobs cannot claim the same final components. Incoming supplier deliveries are not available until a receipt is recorded.'));
 screens['products/material']=()=>{const m=S.state.materials.find(m=>m.id===(A.params.get('id')||'MAT-BLACK'));if(!m)throw Error('Material not found.');const available=S.available(m),jobs=S.state.orders.flatMap(o=>o.items.filter(i=>i.frame===m.frame||m.frame==='packing').filter(i=>i.reserved&&!i.consumed).map(i=>[link('orders/job?id='+o.id+'&item='+i.id,o.id+' / '+i.id),i.qty,esc(o.owner),esc(o.originalDue)]));return heading(m.name,m.id+' · quantities in '+m.unit,link('products/materials','← Materials')+grid(panel('Stock & reservations',facts([['Ownership',m.supplierOwned?'Supplier-owned; exact stock unknown':'Studio on-hand stock'],['Usable stock',m.supplierOwned?'Unknown':String(m.stock)],['Reserved',String(available.reserved)],['Available to promise',m.supplierOwned?'Confirm supplier allocation':String(available.free)],['Incoming',m.incoming+' · not yet received']]))+table('Owned reservations',['Order / job','Quantity','Owner','Original promise'],jobs)+panel('Movement history',m.history.length?table('Stock movements',['Type','Quantity','Reason'],m.history.map(h=>[esc(h.kind),h.qty,esc(h.reason)])):'<p class="small">No local stock movements recorded yet.</p>'),panel('Record a stock movement',form('material',select('kind','Movement',['Receipt','Waste','Count correction'])+field('qty','Quantity',1,'number','Count correction accepts a signed adjustment.')+textarea('reason','Receipt reference / reason'),'Record stock movement',{id:m.id}))+panel('Supplier confirmation',facts([['Supplier',esc(m.supplier)],['Lead time',esc(m.lead)],['Last checked',esc(m.confirmed)],['Contact',esc(m.contact||'Sample supplier contact — owner to confirm')],['Confirmed availability',esc(m.availability||'No separate supplier confirmation')]])+actions(button('supplier','Update supplier confirmation',{id:m.id},'button secondary')))));};
 forms.material=(d,{id})=>{S.guard('catalogue');const qty=Number(d.qty);if(!Number.isInteger(qty)||qty===0||d.kind!=='Count correction'&&qty<1)throw Error('Use a whole component quantity; receipt and waste must be positive.');const m=S.state.materials.find(m=>m.id===id),delta=d.kind==='Waste'?-qty:qty;commit(id,'Material '+d.kind,()=>{if(m.supplierOwned)throw Error('Supplier-owned stock has no exact studio count. Update availability or switch after a verified studio receipt.');if(m.stock+delta<0)throw Error('This movement would make stock negative.');m.stock+=delta;if(d.kind==='Receipt')m.incoming=Math.max(0,m.incoming-qty);m.history.unshift({at:S.now(),kind:d.kind,qty:delta,reason:d.reason});if(S.available(m).free<0)S.state.orders.filter(o=>o.items.some(i=>i.reserved&&!i.consumed&&(i.frame===m.frame||m.frame==='packing'))).forEach(o=>S.task(o,'Reserved material shortage','products/material?id='+id));},d.reason);};
 handlers.supplier=({id})=>{const m=S.state.materials.find(m=>m.id===id);modal('Update supplier availability','Use a confirmed check, not a promised incoming delivery. Supplier-owned stock does not invent an on-hand count.',field('supplier','Supplier',m.supplier)+field('contact','Contact reference',m.contact||'supplier@example.test')+field('lead','Lead time',m.lead)+select('availability','Confirmed availability',['Available','Limited','Unavailable','Not confirmed'],m.availability)+check('supplierOwned','Stock is held by the supplier; exact studio quantity is unknown',m.supplierOwned)+textarea('reason','Confirmation reference and date'),d=>{S.guard('catalogue');S.mutate(id,'Supplier availability check',()=>Object.assign(m,{supplier:d.supplier,contact:d.contact,lead:d.lead,availability:d.availability,supplierOwned:Boolean(d.supplierOwned),confirmed:S.now(),confirmation:d.reason}));},'Save confirmation');};
 const template=[['artwork_id','title','black_price_inr','version'],['ART-001','The Bridge of Blue Stone',21000,1]];
 screens['products/import']=()=>heading('Import records','Preview each row, resolve mistakes and apply valid drafts deliberately.',notice('Reusable catalogue CSV','Columns: artwork_id, title, black_price_inr, version. Existing codes update reviewed records; a NEW- code creates a draft. Imports never publish.')+actions(button('import-template','Download CSV template',{},'button secondary'),button('import-sample','Load mixed sample rows',{},'button secondary'))+panel('Choose a CSV',form('import-preview',`<label class="field"><span>Catalogue CSV file</span><input type="file" name="file" accept=".csv,text/csv" required><small>UTF-8 CSV, up to 2 MB, maximum 500 rows.</small></label>`,'Preview CSV rows'))+(S.state.importRows.length?table('Import preview',['Row / code','Proposed title','Price','Version','Validation'],S.state.importRows.map(r=>[r.row+' / '+esc(r.id),esc(r.title),money(r.price),esc(r.version),pill(r.error||r.result||'Valid draft update',r.error?'bad':'')]))+actions(button('import-apply','Apply valid rows'),button('import-clear','Clear preview',{},'button secondary')):'')+notice('Conflicts and export safety','A newer edit blocks that row at application. Formula-like content is rejected on import and neutralised in CSV downloads. Approved public sources are never overwritten.'));
 function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('A quoted CSV value is not closed.');if(cell||row.length){row.push(cell);rows.push(row);}return rows;}
 function validateRows(rows){const heads=rows.shift()?.map(x=>x.replace(/^\uFEFF/,'').trim());if(!heads||heads.join(',')!==template[0].join(','))throw Error('Use the template headers in order: '+template[0].join(', '));if(rows.length>500)throw Error('Use 500 rows or fewer in this prototype.');const counts={};rows.forEach(r=>counts[r[0]]=(counts[r[0]]||0)+1);return rows.map((r,n)=>{const [id,title,price,version]=r,p=S.state.products.find(p=>p.id===id),amount=Math.round(Number(price)*100);let error='';if(r.length!==4)error='Expected four columns';else if(!id||!title?.trim()||!price||!version)error='Missing required value';else if(counts[id]>1)error='Duplicate artwork code';else if(r.some(v=>/^\s*[=+@-]/.test(v)))error='Formula-like value blocked';else if(!Number.isSafeInteger(amount)||amount<=0)error='Invalid positive price';else if(p&&p.version!==Number(version))error='Conflict: newer artwork revision';else if(!p&&!/^NEW-[A-Z0-9-]+$/i.test(id))error='Unknown code; new drafts must use NEW-';return {row:n+2,id,title,price:amount,version:Number(version),error,result:''};});}
 handlers['import-template']=()=>download('aalishaan-catalogue-template.csv',S.csv(template));
 handlers['import-sample']=()=>{S.guard('catalogue');const rows=[template[0],['ART-001','Bridge title — reviewed draft',21000,S.state.products.find(p=>p.id==='ART-001').version],['ART-002','Duplicate row A',21000,1],['ART-002','Duplicate row B',21000,1],['ART-003','',21000,1],['ART-004','=HYPERLINK("bad")',21000,1],['ART-005','Stale update',21000,0],['NEW-DEMO-1','New sample artwork',21000,1]];commit('IMPORT','Preview sample import',()=>S.state.importRows=validateRows(rows));};
 forms['import-preview']=async d=>{S.guard('catalogue');if(!d.file?.size||d.file.size>2*1024*1024||!/\.csv$/i.test(d.file.name))throw Error('Choose a CSV file up to 2 MB.');const rows=validateRows(parseCSV(await d.file.text()));commit('IMPORT','Preview catalogue CSV',()=>S.state.importRows=rows);};
 handlers['import-apply']=()=>{S.guard('catalogue');const rows=S.state.importRows.filter(r=>!r.error&&!r.result);if(!rows.length){toast('No unapplied valid rows are available.',true);return;}modal('Apply '+rows.length+' valid draft rows?','Each record version is checked again. Invalid/conflicting rows stay visible and no draft is published.',list(rows.map(r=>esc(r.id)+' · '+esc(r.title))),()=>S.mutate('IMPORT','Apply validated import',()=>{for(const r of rows){const p=S.state.products.find(p=>p.id===r.id);if(p&&p.version!==r.version){r.error='Conflict at application; skipped';continue;}if(p){remember(p,'Validated CSV import');p.title=r.title;p.prices.black=r.price;p.status='Draft';}else{const draft={id:r.id,title:r.title,slug:r.id.toLowerCase(),copy:'',collection:S.state.products[0]?.collection||'',style:'',rooms:[],moods:[],lead:'5-7 working days',featured:false,status:'Draft',version:1,history:[],rights:false,sample:false,fileApproved:false,fileVersion:'v1',newDraft:true,image:'',prices:{black:r.price,white:0,'antique-gold':0},cms:{orientation:'Portrait',palettes:[],hook:'',seoTitle:r.title,seoDescription:'',alt:r.title,searchKeywords:'',media:{},suggestedFrame:'black'}};S.state.products.push(draft);}r.result='Applied as draft';}}),'Apply valid drafts');};
 handlers['import-clear']=()=>{S.state.importRows=[];S.save();render();};
 A.productHelpers={readiness};
})();
